for (i in 1:3) {
  print(i * 10)
}

fruits <- c("apple", "pear")
for (f in fruits) cat("I like", f, "\n")
for (i in seq_along(fruits)) cat(i, fruits[i], "\n")

square <- function(x) {
  x^2
}
square(4)

greet <- function(name, greeting = "Hello") {
  paste(greeting, name)
}
greet("Ali")
greet("Ali", greeting = "Hi")

r <- tryCatch({
  log(-1)
}, warning = function(w) "warning caught",
   error = function(e) "error caught")
print(r)

check <- function(x) {
  if (!is.numeric(x)) stop("need a number")
  x * 2
}
tryCatch(check("a"), error = function(e) conditionMessage(e))

tryCatch({
  stop("boom")
}, error = function(e) cat("handled\n"),
   finally = cat("cleanup\n"))

ex.sol:
safe_div <- function(a, b) {
  if (b == 0) stop("division by zero")
  a / b
}
print(tryCatch(safe_div(1, 0), error = function(e) conditionMessage(e)))

